97: /* Project roadmap */
98: .project-roadmap{margin:18px 0 24px;padding:20px;border:1px solid #343d30;background:linear-gradient(145deg,#1b231b,#171d17);box-shadow:0 12px 30px #080c0866}
99: .roadmap-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin-bottom:12px}
100: .project-roadmap h2{margin:7px 0 0;color:#e8e4d4;font-size:23px;font-weight:500;letter-spacing:-.6px}
101: .project-roadmap h2 em{color:var(--gold);font-family:Georgia,serif;font-weight:400}
102: .roadmap-version,.roadmap-step{color:#a7ad97;font:7px var(--mono);letter-spacing:1px}
103: .roadmap-version{padding:7px 9px;border:1px solid #404738;background:#20271e;white-space:nowrap}
104: .roadmap-intro{max-width:920px;margin:0 0 14px;color:#a8af9e;font-size:11px;line-height:1.65}
105: .roadmap-now{display:flex;align-items:flex-start;gap:11px;margin:0 0 14px;padding:12px;border:1px solid #665637;background:#2b291e}
106: .roadmap-pulse{width:7px;height:7px;flex:none;margin-top:3px;border-radius:50%;background:#c9a65d;box-shadow:0 0 10px #c9a65d88}
107: .roadmap-now div{display:grid;gap:5px}.roadmap-now b{color:#e4cc91;font:8px var(--mono);letter-spacing:.7px}.roadmap-now span:not(.roadmap-pulse){color:#c3c4b3;font-size:10px;line-height:1.5}
108: .roadmap-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
109: .roadmap-card{min-width:0;padding:13px;border:1px solid #30392e;background:#1a211a}
110: .roadmap-step{color:#c3a86b}.roadmap-card h3{margin:7px 0 9px;color:#e4e3d6;font-size:13px;font-weight:600}
