function beginNpcAim(actor, target) {
  const [x, y] = actorTile(target);
  actor.heading = x < actorTile(actor)[0] ? 'W' : x > actorTile(actor)[0] ? 'E' : y < actorTile(actor)[1] ? 'N' : 'S';
